        "guide.fillWater.title": ("ملء خزان الماء", "Fill the water tank"),
        "guide.fillWater.intro": ("استخدم ماء شرب باردًا ونظيفًا فقط.", "Use only fresh, cold drinking water."),
        "guide.fillWater.step.1": ("اسحب خزان الماء من الماكينة برفق.", "Gently pull the water tank out of the machine."),
        "guide.fillWater.step.2": ("اشطفه ثم املأه بماء شرب بارد حتى خط الامتلاء. لا تستخدم ماءً غازيًا أو أي سائل آخر.", "Rinse it and fill it with cold drinking water up to the MAX line. Never use sparkling water or any other liquid."),
        "guide.fillWater.step.3": ("أعد الخزان إلى مكانه واضغطه حتى يثبت تمامًا.", "Put the tank back and push it until it sits firmly."),
        "guide.fillWater.step.4": ("يزول التنبيه وحده عندما تتعرف الماكينة على الخزان. إن لم يزل فتأكد أنه مدفوع للنهاية.", "The alert clears by itself once the machine detects the tank. If it doesn't, check the tank is pushed all the way in."),

        "guide.fillBeans.title": ("إضافة حبوب البن", "Add coffee beans"),
        "guide.fillBeans.intro": ("الحاوية في أعلى الماكينة، ولها غطاء يُفتح للأعلى.", "The container is on top of the machine, with a lid that opens upward."),
        "guide.fillBeans.step.1": ("افتح غطاء حاوية البن في أعلى الماكينة.", "Open the bean container lid on top of the machine."),
        "guide.fillBeans.step.2": ("صب حبوب بن محمصة. لا تضع بنًا مطحونًا ولا حبوبًا منكّهة أو مكرملة أو زيتية في هذه الحاوية.", "Pour in roasted coffee beans. Never put ground coffee or flavoured, caramelised or oily beans in this container."),
        "guide.fillBeans.step.3": ("أغلق الغطاء جيدًا ليحفظ النكهة.", "Close the lid well to keep the aroma."),
        "guide.fillBeans.step.4": ("حضّر مشروبك من جديد. قد يكون أول كوب بعد الملء أخف قليلًا.", "Make your drink again. The first cup after refilling may be slightly milder."),

        "guide.emptyContainers.title": ("إفراغ الحاوية وصينية التقطير", "Empty the grounds and drip tray"),
        "guide.emptyContainers.intro": ("الصينية والحاوية في مقدمة الماكينة أسفل فوهة القهوة.", "The drip tray and grounds container are at the front, below the coffee spout."),
        "guide.emptyContainers.step.1": ("اسحب صينية التقطير من مقدمة الماكينة ببطء، فقد تحتوي على ماء.", "Slowly pull the drip tray out of the front of the machine; it may hold water."),
        "guide.emptyContainers.step.2": ("أخرج حاوية البن المستعمل وأفرغها في سلة المهملات.", "Take out the grounds container and empty it into the bin."),
        "guide.emptyContainers.step.3": ("أفرغ صينية التقطير واشطفها بالماء.", "Empty the drip tray and rinse it with water."),
        "guide.emptyContainers.step.4": ("أعد الحاوية ثم الصينية إلى مكانهما حتى النهاية.", "Put the container back, then slide the tray all the way in."),
        "guide.emptyContainers.step.5": ("أفرغ الحاوية دائمًا عندما تطلب الماكينة ذلك؛ إعادتها دون إفراغ تجعل العدّ خاطئًا.", "Always empty the container when asked; putting it back full makes the machine's count wrong."),

        "guide.milkCarafe.title": ("تنظيف إبريق الحليب", "Clean the milk carafe"),
        "guide.milkCarafe.intro": ("نظّف دورة الحليب بعد كل مشروب بالحليب، وفكّ الإبريق للغسل مرة يوميًا.", "Flush the milk circuit after every milk drink, and take the carafe apart to wash it once a day."),
        "guide.milkCarafe.step.1": ("بعد مشروب الحليب اترك الإبريق مركّبًا، وعندما تطلب الماكينة التنظيف أدر مقبض الرغوة إلى وضع التنظيف أو أكّد على الشاشة.", "After a milk drink, leave the carafe attached. When the machine asks, turn the froth knob to the clean position or confirm on the screen."),
        "guide.milkCarafe.step.2": ("ضع كوبًا تحت فوهة الحليب؛ يخرج ماء ساخن وبخار لتنظيف الدورة.", "Place a cup under the milk spout; hot water and steam flush the circuit."),
        "guide.milkCarafe.step.3": ("افصل الإبريق وضع الحليب المتبقي في الثلاجة.", "Detach the carafe and put the leftover milk in the fridge."),
        "guide.milkCarafe.step.4": ("مرة يوميًا: فكّ الغطاء والفوهة وأنبوب السحب ومقبض الرغوة.", "Once a day: take off the lid, the spout, the intake tube and the froth knob."),
        "guide.milkCarafe.step.5": ("اغسل الأجزاء بماء دافئ ومنظف خفيف، واشطفها جيدًا.", "Wash the parts in warm water with mild detergent and rinse well."),
        "guide.milkCarafe.step.6": ("أعد تركيب كل الأجزاء قبل الاستخدام؛ التركيب الناقص يسبب تسربًا أو رغوة ضعيفة.", "Reassemble every part before use; a missing part causes leaks or poor froth."),

        "guide.brewingUnit.title": ("تنظيف وحدة التحضير", "Clean the brewing unit"),
        "guide.brewingUnit.intro": ("مرة أسبوعيًا تقريبًا. لا تُخرج الوحدة والماكينة تعمل.", "About once a week. Never remove the unit while the machine is on."),
        "guide.brewingUnit.step.1": ("أطفئ الماكينة بزر التشغيل وانتظر حتى تنطفئ تمامًا.", "Turn the machine off with the power button and wait until it is completely off."),
        "guide.brewingUnit.step.2": ("افتح باب الصيانة على جانب الماكينة.", "Open the service door on the side of the machine."),
        "guide.brewingUnit.step.3": ("اضغط زري التحرير الملونين في الوحدة معًا واسحبها للخارج.", "Press the two coloured release buttons on the unit together and pull it out."),
        "guide.brewingUnit.step.4": ("اشطفها بماء فاتر جارٍ فقط، بلا منظفات وبلا غسالة صحون.", "Rinse it under lukewarm running water only, with no detergent and no dishwasher."),
        "guide.brewingUnit.step.5": ("نظّف مكان الوحدة داخل الماكينة من بقايا البن بفرشاة ناعمة.", "Brush away coffee residue from the unit's compartment."),
        "guide.brewingUnit.step.6": ("اتركها تجف، ثم أدخلها حتى تسمع نقرة دون الضغط على زري التحرير.", "Let it dry, then slide it in until it clicks, without pressing the release buttons."),
        "guide.brewingUnit.step.7": ("أغلق باب الصيانة. لن تعمل الماكينة إن كان الباب مفتوحًا أو الوحدة غير مثبتة.", "Close the service door. The machine won't start if the door is open or the unit is loose."),

        "guide.waterFilter.title": ("تركيب فلتر الماء", "Fit the water filter"),
        "guide.waterFilter.intro": ("الفلتر يقلل الترسبات. غيّره كل شهرين تقريبًا أو عندما تطلب الماكينة.", "The filter reduces scale. Replace it about every two months, or when the machine asks."),
        "guide.waterFilter.step.1": ("أخرج الفلتر الجديد من غلافه، وأدر قرص التاريخ إلى موعد التغيير القادم.", "Unwrap the new filter and turn its date dial to the next change date."),
        "guide.waterFilter.step.2": ("مرّر ماء الصنبور في فتحته الوسطى حتى يخرج من الفتحات الجانبية، نحو دقيقة.", "Run tap water into its centre opening until it flows out of the side openings, about a minute."),
        "guide.waterFilter.step.3": ("أخرج خزان الماء، وضع الفلتر في مكانه داخله واضغطه للأسفل حتى يثبت.", "Take out the water tank, place the filter in its seat inside, and press it down."),
        "guide.waterFilter.step.4": ("املأ الخزان بالماء وأعده إلى الماكينة.", "Fill the tank with water and put it back."),
        "guide.waterFilter.step.5": ("من قائمة الماكينة أكّد تركيب الفلتر. ضع وعاءً سعته نصف لتر على الأقل تحت الفوهة لأن الماكينة ستصب ماءً لتفعيله.", "Confirm the filter in the machine's menu. Put a container of at least half a litre under the spout; the machine pours water to activate it."),
        "guide.waterFilter.step.6": ("أفرغ الوعاء بعد انتهاء التفعيل. الفلتر جاهز.", "Empty the container when activation ends. The filter is ready."),

        "guide.descaling.title": ("إزالة الترسبات", "Descaling"),
        "guide.descaling.intro": ("تستغرق نحو 45 دقيقة. تحتاج مزيل ترسبات De'Longhi ووعاءً سعته لتران على الأقل. يبدأ البرنامج من قائمة الماكينة نفسها، ولا يستطيع التطبيق بدأه.", "Takes about 45 minutes. You need De'Longhi descaler and a container of at least 2 litres. The programme starts from the machine's own menu; the app cannot start it."),
        "guide.descaling.step.1": ("جهّز مزيل الترسبات ووعاءً كبيرًا وماءً نظيفًا. لا تستخدم الخل أبدًا.", "Get the descaler, a large container and fresh water ready. Never use vinegar."),
        "guide.descaling.step.2": ("إن كان فلتر الماء مركّبًا فأخرجه من الخزان.", "If a water filter is fitted, take it out of the tank."),
        "guide.descaling.step.3": ("أفرغ صينية التقطير وحاوية البن المستعمل ثم أعدهما.", "Empty the drip tray and grounds container, then put them back."),
        "guide.descaling.step.4": ("صب مزيل الترسبات في الخزان حتى العلامة المحددة، ثم أضف الماء حتى العلامة التالية كما توضح الماكينة.", "Pour the descaler into the tank up to its mark, then add water up to the next mark, as the machine shows."),
        "guide.descaling.step.5": ("ضع الوعاء الكبير تحت فوهات القهوة والماء والحليب.", "Put the large container under the coffee, water and milk spouts."),
        "guide.descaling.step.6": ("ابدأ برنامج إزالة الترسبات من قائمة الصيانة في الماكينة وأكّد. يخرج المحلول على دفعات؛ انتظر.", "Start descaling from the machine's maintenance menu and confirm. The solution comes out in bursts; wait."),
        "guide.descaling.step.7": ("عندما تطلب الماكينة، اشطف الخزان واملأه بماء نظيف حتى خط الامتلاء، وأفرغ الوعاء وأعده.", "When asked, rinse the tank and fill it with fresh water to MAX, then empty the container and put it back."),
        "guide.descaling.step.8": ("تبدأ دورة الشطف. بعد انتهائها أفرغ الوعاء وصينية التقطير.", "The rinse cycle runs. When it ends, empty the container and the drip tray."),
        "guide.descaling.step.9": ("أعد فلتر الماء إن كنت تستخدمه، وامسح أي رذاذ من المحلول. احفظ المحلول بعيدًا عن الأطفال.", "Refit the water filter if you use one and wipe any splashes. Keep the descaler away from children."),

        // MARK: Diagnostics
        "diagnostics.title": ("فحص الماكينة", "Machine check"),
        "diagnostics.hint": ("يبحث عن ماكينتك ويختبر طريقة اتصالها، ثم يعطيك تقريرًا ترسله.", "Finds your machine, tests how it talks, and gives you a report to send."),
        "diagnostics.intro": ("قرّب الهاتف من الماكينة وشغّلها. ابدأ البحث، ثم اختر الجهاز الذي يبدو أنه ماكينتك ليُفحص. في النهاية شارك التقرير.", "Keep your phone near the machine and turn it on. Start the scan, then pick the device that looks like your machine. Finally, share the report."),
        "diagnostics.scan": ("ابدأ البحث", "Start scan"),
        "diagnostics.scanning": ("جارٍ البحث…", "Scanning…"),
        "diagnostics.inspecting": ("جارٍ فحص %@…", "Checking %@…"),
        "diagnostics.result": ("النتيجة", "Result"),
        "diagnostics.devices": ("الأجهزة القريبة", "Nearby devices"),
        "diagnostics.services": ("الخدمات التي وُجدت", "Services found"),
        "diagnostics.traffic": ("آخر الرسائل مع الماكينة", "Recent machine messages"),
        "diagnostics.share": ("شارك التقرير", "Share report"),
        "diagnostics.copy": ("انسخ التقرير", "Copy report"),
        "diagnostics.copied": ("نُسخ التقرير.", "Report copied."),
        "diagnostics.inspect.hint": ("اضغط مرتين لفحص هذا الجهاز.", "Double-tap to check this device."),
        "diagnostics.signal": ("قوة الإشارة %d", "Signal %d"),
        "diagnostics.ecamAdvertised": ("يعلن خدمة ماكينات De'Longhi", "Advertises the De'Longhi service"),
        "diagnostics.likelyMachine": ("يبدو أنه ماكينة De'Longhi", "Looks like a De'Longhi machine"),
        "diagnostics.ecamService": ("خدمة ماكينات De'Longhi (ECAM)", "De'Longhi machine service (ECAM)"),
        "diagnostics.unnamed": ("جهاز بلا اسم", "Unnamed device"),
        "diagnostics.foundMachine": ("وُجد جهاز يبدو أنه ماكينتك: %@", "Found a device that looks like your machine: %@"),
        "diagnostics.timeout": ("انتهت مهلة الفحص.", "The check timed out."),
        "diagnostics.done": ("انتهى الفحص.", "Check finished."),
        "diagnostics.verdict.ecamWorks": ("ممتاز: ماكينتك تفهم بروتوكول البلوتوث المعروف، ويمكن التحكم بها من التطبيق.", "Great: your machine speaks the known Bluetooth protocol and can be controlled from the app."),
        "diagnostics.verdict.ecamSilent": ("وُجدت خدمة ماكينات De'Longhi لكن الماكينة لم تردّ. شغّلها وأعد الفحص، ثم أرسل التقرير.", "The De'Longhi service is there but the machine did not answer. Turn it on, check again, then send the report."),
        "diagnostics.verdict.noEcam": ("هذا الجهاز لا يستخدم البروتوكول المعروف. أرسل التقرير لنعرف طريقة اتصاله.", "This device does not use the known protocol. Send the report so we can learn how it talks."),
        "diagnostics.verdict.nothingFound": ("لم يُعثر على أي جهاز. تأكد أن البلوتوث يعمل وأن الماكينة قريبة ومشغّلة.", "Nothing found. Check Bluetooth is on and the machine is nearby and on."),
        "diagnostics.verdict.noMachineName": ("وُجدت أجهزة لكن لا يبدو أي منها ماكينة De'Longhi. جرّب فحص الأقرب إشارة، وأرسل التقرير.", "Devices found, but none looks like a De'Longhi machine. Try checking the strongest one and send the report."),

