        // MARK: Onboarding
        "onboarding.welcome.title": ("أهلًا بك في قهوتي", "Welcome to Coffee Access"),
        "onboarding.welcome.body": ("تطبيق مستقل لماكينة القهوة الأوتوماتيكية، صُمّم أولًا لمستخدمي VoiceOver.", "An independent app for your bean-to-cup machine, designed first for VoiceOver users."),
        "onboarding.feature.1": ("47 مشروبًا في خمس قوائم وسبع مجموعات، بعناوين واضحة.", "47 drinks in five menus and seven collections, with clear headings."),
        "onboarding.feature.2": ("تخصيص القوة والكمية والحرارة بالسحب لأعلى ولأسفل.", "Set strength, amount and temperature by swiping up and down."),
        "onboarding.feature.3": ("إعلانات صوتية لكل مرحلة وتنبيه.", "Spoken updates for every step and alert."),
        "onboarding.feature.4": ("اطلب قهوتك من Siri.", "Ask Siri for your coffee."),
        "onboarding.connection.title": ("كيف نصل إلى ماكينتك؟", "How should we reach your machine?"),
        "onboarding.connection.body": ("اختر الاتصال بماكينتك عبر البلوتوث، أو ابدأ بوضع التجربة لتتعلّم التطبيق أولًا. يمكنك التغيير لاحقًا من الإعدادات.", "Connect to your machine over Bluetooth, or start in demo mode to learn the app first. You can change this later in Settings."),
        "onboarding.connection.note": ("إن لم تتصل ماكينتك، افتح «فحص الماكينة» من تبويب الماكينة وأرسل التقرير.", "If your machine doesn't connect, open Machine check from the Machine tab and send the report."),
        "onboarding.profile.title": ("ما اسمك؟", "What's your name?"),
        "onboarding.profile.body": ("يُستخدم للترحيب ولاسم ملفك الشخصي. للماكينة أربعة ملفات لكل منها مفضلته.", "Used for greetings and your profile name. The machine has four profiles, each with its own favorites."),
        "onboarding.start": ("ابدأ", "Get started"),

